77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        String normalizedAddress = normalizeAddress(owner.getAddress());
108	        if (normalizedAddress.isEmpty()) {
109	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
110	                "Address must not be blank after normalization");
111	        }
112	        owner.setAddress(normalizedAddress);
113	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
114	        owner.setTelephone(normalizedTelephone);
115	        owner.setEmail(normalizeEmail(owner.getEmail()));
116	        validatePostcode(owner.getPostcode(), owner.getCity());
117	        java.time.LocalDate serverDate = java.time.LocalDate.now();
118	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
119	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
120	                "Registration date must not be later than the current server date");
121	        }
122	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
123	            ? owner.getRegistrationDate() : serverDate;
124	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
125	        owner.setRegistrationDate(businessDate);
126	        long createdToday = this.clinicService.findAllOwners().stream()
127	            .map(Owner::getRegistrationDate)
128	            .filter(businessDate::equals)
129	            .count();
130	        if (createdToday >= 100) {
131	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
132	                "The maximum number of owners for today has already been reached");
133	        }
134	        owner.setBulkSignupWarning(createdToday > 80);
135	        String lastNameKey = normalizeForHousehold(owner.getLastName());
136	        String addressKey = normalizeForHousehold(owner.getAddress());
137	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
138	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(lastNameKey)
139	                && normalizeForHousehold(existing.getAddress()).equals(addressKey))
140	            .toList();
141	        String householdId = null;
142	        if (!householdMembers.isEmpty() && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
143	            householdId = householdId(lastNameKey, addressKey);
144	            owner.setHouseholdId(householdId);
145	        }
146	        // All duplicate detection is now expressed through the single derived identityKey
147	        // (telephone|email|householdId); a new owner is rejected only when its whole key matches.
148	        String identityKey = owner.getIdentityKey();
149	        boolean identityInUse = this.clinicService.findAllOwners().stream()
150	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
151	        if (identityInUse) {
152	            throw new ResponseStatusException(HttpStatus.CONFLICT,
153	                "An owner with this identity already exists");
154	        }
155	        if (householdId != null) {
156	            for (Owner member : householdMembers) {
157	                if (!householdId.equals(member.getHouseholdId())) {
158	                    member.setHouseholdId(householdId);
159	                    this.clinicService.saveOwner(member);
160	                }
161	            }
162	        }
163	        String cityKey = normalizeForHousehold(owner.getCity());
164	        long cityCount = this.clinicService.findAllOwners().stream()
165	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
166	            .count();
167	        if (cityCount >= 50) {
168	            throw new ResponseStatusException(HttpStatus.CONFLICT,
169	                "This city already has the maximum number of owners");
170	        }
171	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
172	        owner.setHouseholdSize(householdMembers.size() + 1);
173	        owner.setCustomerCode(customerCode(owner.getCity(), owner.getPostcode(),
174	            owner.getTelephone(), owner.getLastName()));
175	        this.clinicService.saveOwner(owner);
176	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
177	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
178	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
179	        headers.setLocation(UriComponentsBuilder.newInstance()
180	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
181	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
182	    }
183	
184	    /**
185	     * Rolls a registration date forward to a business day. When {@code date} falls on a Saturday or
186	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
187	     * to the effective registration date (whether supplied in the request or defaulted to the server
188	     * date) so that every stored {@code registrationDate}, and any value derived from it, lands on a
189	     * business day.
190	     *
191	     * @param date the effective registration date
192	     * @return the same date if it is a weekday, otherwise the following Monday
193	     */
194	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
195	        return switch (date.getDayOfWeek()) {
196	            case SATURDAY -> date.plusDays(2);
197	            case SUNDAY -> date.plusDays(1);
198	            default -> date;
199	        };
200	    }
201	
202	    /**
203	     * Counts the owners that already exist (before the current create) whose first and last names
204	     * both match the supplied names, compared case-insensitively. The returned value is captured on
205	     * the new owner at creation time and does not change as further owners are added later.
206	     *
207	     * @param firstName the new owner's first name
208	     * @param lastName  the new owner's last name
209	     * @return the number of pre-existing namesake owners
210	     */
211	    private int namesakeCount(String firstName, String lastName) {
212	        return (int) this.clinicService.findAllOwners().stream()
213	            .filter(existing -> existing.getFirstName() != null
214	                && existing.getFirstName().equalsIgnoreCase(firstName)
215	                && existing.getLastName() != null
216	                && existing.getLastName().equalsIgnoreCase(lastName))
217	            .count();
218	    }
219	
220	    /**
221	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where
222	     * {@code REGION} is the canonical region derived from the owner's postcode (falling back to
223	     * the city when the postcode is absent or in no known range, see
224	     * {@link org.springframework.samples.petclinic.mapper.Localities#forCityAndPostcode}), and
225	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the
226	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike
227	     * the previous city-prefixed scheme it carries no per-city sequence number, so the identity is
228	     * a pure function of the owner's region, telephone and last name.
229	     *
230	     * @param city                the owner's city
231	     * @param postcode            the owner's postcode, may be {@code null}
232	     * @param normalizedTelephone the owner's telephone, already normalized to E.164
233	     * @param lastName            the owner's last name
234	     * @return the assigned customer code
235	     */
236	    private String customerCode(String city, String postcode, String normalizedTelephone, String lastName) {
237	        String region = org.springframework.samples.petclinic.mapper.Localities
238	            .forCityAndPostcode(city, postcode);
239	        String hash8 = sha256UpperHex((normalizedTelephone == null ? "" : normalizedTelephone)
240	            + (lastName == null ? "" : lastName), 8);
241	        return region + "-" + hash8;
242	    }
243	
244	    /**
245	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
246	     * UTF-8 bytes of {@code value}.
247	     *
248	     * @param value  the source value to hash
249	     * @param length the number of leading hex characters to return
250	     * @return the leading upper-case hex characters of the digest
251	     */
252	    private String sha256UpperHex(String value, int length) {
253	        try {
254	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
255	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
256	            StringBuilder sb = new StringBuilder(digest.length * 2);
257	            for (byte b : digest) {
258	                sb.append(String.format("%02x", b));
259	            }
260	            return sb.substring(0, length).toUpperCase(java.util.Locale.ROOT);
261	        }
262	        catch (java.security.NoSuchAlgorithmException e) {
263	            throw new IllegalStateException("SHA-256 not available", e);
264	        }
265	    }
266	
267	    /**
268	     * Normalizes a street address applied whenever an owner is created: leading and trailing
269	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
270	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
271	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
272	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
273	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
274	     * {@code '12 MAIN STREET'}.
275	     *
276	     * @param address the raw address as submitted, or {@code null} when absent
277	     * @return the normalized address, or the empty string when the value is blank
278	     */
279	    private String normalizeAddress(String address) {
280	        String collapsed = (address == null ? "" : address)
281	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
282	        if (collapsed.isEmpty()) {
283	            return "";
284	        }
285	        String[] tokens = collapsed.split(" ");
286	        for (int i = 0; i < tokens.length; i++) {
287	            switch (tokens[i]) {
288	                case "ST" -> tokens[i] = "STREET";
289	                case "RD" -> tokens[i] = "ROAD";
290	                case "AVE" -> tokens[i] = "AVENUE";
291	                default -> { }
292	            }
293	        }
294	        return String.join(" ", tokens);
295	    }
296	
297	    /**
298	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
299	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
300	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
301	     * empty string.
302	     *
303	     * @param value the raw value (last name or address) as submitted
304	     * @return the normalized comparison key
305	     */
306	    private String normalizeForHousehold(String value) {
307	        if (value == null) {
308	            return "";
309	        }
310	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
311	    }
312	
313	    /**
314	     * Derives the stable shared household identifier for a household, keyed on the normalized last
315	     * name and address. Because it is a pure function of those normalized keys, every owner in the
316	     * same household deterministically computes the same value. The identifier is the first 12
317	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
318	     * (the separator prevents distinct name/address pairs from colliding).
319	     *
320	     * @param lastNameKey the normalized last-name comparison key
321	     * @param addressKey  the normalized address comparison key
322	     * @return the stable household identifier
323	     */
324	    private String householdId(String lastNameKey, String addressKey) {
325	        String seed = lastNameKey + "�" + addressKey;
326	        try {
327	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
328	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
329	            StringBuilder sb = new StringBuilder(digest.length * 2);
330	            for (byte b : digest) {
331	                sb.append(String.format("%02x", b));
332	            }
333	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
334	        }
335	        catch (java.security.NoSuchAlgorithmException e) {
336	            throw new IllegalStateException("SHA-256 not available", e);
337	        }
338	    }
339	
340	    /**
341	     * The exact number of national (subscriber) digits required for a given country calling code,
342	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
343	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
344	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
345	     */
346	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
347	        java.util.Map.of("61", 9, "1", 10);
348	
349	    /**
350	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
351	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
352	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
353	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
354	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
355	     * is stored as {@code '+61412345678'}.
356	     *
357	     * <p>In addition, when the number's country code has a fixed national-number length (see
358	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
359	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
360	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
361	     *
362	     * @param telephone the raw telephone number as submitted
363	     * @return the normalized E.164 telephone number
364	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
365	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
366	     *         for its country code
367	     */
368	    private String normalizeTelephone(String telephone) {
369	        String raw = telephone == null ? "" : telephone.trim();
370	        String digits = raw.replaceAll("\\D", "");
371	        String e164;
372	        if (raw.startsWith("+")) {
373	            e164 = "+" + digits;
374	        } else {
375	            if (digits.startsWith("0")) {
376	                digits = digits.substring(1);
377	            }
378	            e164 = "+61" + digits;
379	        }
380	        int digitCount = e164.length() - 1;
381	        if (digitCount < 8 || digitCount > 15) {
382	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
383	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
384	        }
385	        validateNationalNumberLength(e164);
386	        return e164;
387	    }
388	
389	    /**
390	     * Validates that an E.164 number's national-number length is correct for its country code.
391	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
392	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
393	     * following it must match exactly. Country codes without a fixed length are left unchecked.
394	     *
395	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
396	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
397	     *         for the country code
398	     */
399	    private void validateNationalNumberLength(String e164) {
400	        String allDigits = e164.substring(1);
401	        String bestCode = null;
402	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
403	            if (allDigits.startsWith(code)
404	                    && (bestCode == null || code.length() > bestCode.length())) {
405	                bestCode = code;
406	            }
407	        }
408	        if (bestCode == null) {
409	            return;
410	        }
411	        int nationalLength = allDigits.length() - bestCode.length();
412	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
413	        if (nationalLength != required) {
414	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
415	                "Telephone for country code '+" + bestCode + "' must have " + required
416	                    + " national digits");
417	        }
418	    }
419	
420	    /**
421	     * The inclusive 4-digit postcode range permitted for each canonical region, keyed by the
422	     * region derived from the owner's city ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
423	     * {@code Brisbane -> QLD}): NSW {@code 2000-2099}, VIC {@code 3000-3099}, QLD
424	     * {@code 4000-4099}. A city whose region is not listed here accepts any 4-digit postcode.
425	     */
426	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
427	        "NSW", new int[] {2000, 2099},
428	        "VIC", new int[] {3000, 3099},
429	        "QLD", new int[] {4000, 4099});
430	
431	    /**
432	     * Validates an owner's optional postcode against their city's region. The postcode is only
433	     * checked when present (a {@code null} postcode is accepted, keeping the request contract
434	     * backward-compatible). Its four-digit shape is already enforced by Bean Validation on the
435	     * request DTO. When the city maps to a known region (see {@link #REGION_POSTCODE_RANGES}) the
436	     * postcode must fall within that region's inclusive range; a city with no known region accepts
437	     * any 4-digit postcode.
438	     *
439	     * @param postcode the owner's postcode as submitted, or {@code null} when absent
440	     * @param city     the owner's city, used to derive the region whose range applies
441	     * @throws ResponseStatusException with a 400 status when a supplied postcode is out of range
442	     *         for the city's region
443	     */
444	    private void validatePostcode(String postcode, String city) {
445	        if (postcode == null) {
446	            return;
447	        }
448	        String region = org.springframework.samples.petclinic.mapper.Localities.forCity(city);
449	        int[] range = REGION_POSTCODE_RANGES.get(region);
450	        if (range == null) {
451	            return;
452	        }
453	        int value = Integer.parseInt(postcode);
454	        if (value < range[0] || value > range[1]) {
455	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
456	                "Postcode " + postcode + " is not valid for region " + region);
457	        }
458	    }
459	
460	    /**
461	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
462	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
463	     * (absent) or already valid.
464	     *
465	     * @param email the email address as submitted, or {@code null} when absent
466	     * @return the lower-cased email, or {@code null} when absent
467	     */
468	    private String normalizeEmail(String email) {
469	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
470	    }
471	
472	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
473	    @Override
474	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
475	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
476	        if (currentOwner == null) {
